/**
 * 国内主流大模型接入预设。
 *
 * 每个预设包含服务商名称、OpenAI 兼容接口地址、常用模型与品牌图标；
 * 后端只保存「服务商 + 接口地址 + 模型 + 密钥」，因此这里的数据只用于
 * 简化前端配置流程，用户可以随时切换到「自定义」填写任意兼容接口。
 *
 * 图标为单色 SVG path（Simple Icons CC0 / theSVG MIT），渲染时使用 currentColor。
 */
export interface AiProviderPreset {
  id: string;
  /** 显示名称，同时作为保存到后端的 provider 字段。 */
  name: string;
  /** 所属公司/平台。 */
  vendor: string;
  /** 一句话特点，帮助用户选择。 */
  description: string;
  /** OpenAI Chat Completions 兼容接口的基础地址（不含末尾斜杠）。 */
  baseUrl: string;
  /** 官方文档中稳定可用的常用模型。 */
  models: readonly string[];
  /** 获取 API Key 的控制台地址。 */
  apiKeyUrl: string;
  /** 品牌色，用于图标底块。 */
  color: string;
  /** 24×24 viewBox 下的 SVG path 内容，使用 currentColor。 */
  icon: string;
  /** 是否在界面上标记为推荐。 */
  featured?: boolean;
}

