/** 按 id 查找预设。 */
export function findAiProviderPreset(id: string): AiProviderPreset | undefined {
  return AI_PROVIDER_PRESETS.find((preset) => preset.id === id);
}

function normalizeUrl(value?: string): string {
  return (value ?? '').trim().replace(/\/+$/, '').toLowerCase();
}

/**
 * 根据已保存的服务商与接口地址识别预设。
 * 先匹配服务商名称，再匹配接口地址；识别不到时返回自定义。
 */
export function matchAiProviderPreset(provider: string, baseUrl?: string): string {
  const name = provider.trim().toLowerCase();
  const byName = AI_PROVIDER_PRESETS.find(
    (preset) => preset.name.toLowerCase() === name || preset.vendor.toLowerCase() === name,
  );
  if (byName) return byName.id;

  const url = normalizeUrl(baseUrl);
  if (url) {
    const byUrl = AI_PROVIDER_PRESETS.find((preset) => normalizeUrl(preset.baseUrl) === url);
    if (byUrl) return byUrl.id;
  }
  return CUSTOM_PROVIDER_ID;
}
